"""The `elec_bill` and `gas_bill` parsers (D3 §5.6, §13). Every PDF is generated by `make_pdf` or edited from it."""

from datetime import UTC, datetime

import pytest

from energatron.adapters.sources.bill_pdf import ELEC_BILL, GAS_BILL, BillPdfParser
from energatron.core.errors import InvalidInputError
from energatron.core.models.catalog import SourceType
from energatron.ports.sources import SourceParser
from tests.fixtures.make_sources import make_pdf

PARSERS = (ELEC_BILL, GAS_BILL)
NAME = "bill.pdf"


def reason(parser: BillPdfParser, data: bytes) -> str:
    with pytest.raises(InvalidInputError) as caught:
        parser.inspect(NAME, data)
    value = caught.value.details["reason"]
    assert isinstance(value, str)
    assert caught.value.details["source"] == parser.source.value
    return value


def test_two_instances_one_per_source_version_1() -> None:
    elec: SourceParser = ELEC_BILL
    gas: SourceParser = GAS_BILL
    assert elec.source is SourceType.ELEC_BILL and gas.source is SourceType.GAS_BILL
    assert elec.version == gas.version == 1
    assert isinstance(ELEC_BILL, BillPdfParser) and isinstance(GAS_BILL, BillPdfParser)


@pytest.mark.parametrize("parser", PARSERS)
def test_detect_is_content_only_never_filename(parser: BillPdfParser) -> None:
    data = make_pdf(creation_date="D:20250304050607")
    for name in (NAME, "Electricity bill.PDF", "x"):
        detection = parser.detect(name, data)
        assert detection is not None and detection.evidence == ("content",)
        assert detection.source is parser.source
    assert parser.detect(NAME, b"not a pdf") is None
    assert parser.detect(NAME, b"") is None


@pytest.mark.parametrize("parser", PARSERS)
def test_detect_needs_only_the_head(parser: BillPdfParser) -> None:
    data = make_pdf(creation_date="D:20250304050607") + b"%" * (70 * 1024)
    detection = parser.detect(NAME, data[: 64 * 1024])
    assert detection is not None and detection.evidence == ("content",)


@pytest.mark.parametrize("parser", PARSERS)
def test_inspect_takes_source_ts_from_the_pdf_metadata(parser: BillPdfParser) -> None:
    info = parser.inspect(NAME, make_pdf(creation_date="D:20250304050607+10'30'"))
    assert info.source_ts == datetime.fromisoformat("2025-03-04T05:06:07+10:30")
    assert info.coverage is None
    assert info.extra == {"source_ts_from": "pdf_metadata"}
    assert info.identifiers == {}
    assert info.extension == ".pdf"


def test_a_naive_date_stays_naive_and_utc_stays_utc() -> None:
    assert ELEC_BILL.inspect(NAME, make_pdf(creation_date="D:20250304050607")).source_ts.tzinfo is None
    utc = GAS_BILL.inspect(NAME, make_pdf(creation_date="D:20250304050607Z", info_in_objstm=True)).source_ts
    assert utc == datetime(2025, 3, 4, 5, 6, 7, tzinfo=UTC)


@pytest.mark.parametrize("parser", PARSERS)
def test_trailing_whitespace_after_eof_is_fine(parser: BillPdfParser) -> None:
    assert parser.inspect(NAME, make_pdf(creation_date="D:2025") + b"\r\n  \n").source_ts == datetime(2025, 1, 1)


@pytest.mark.parametrize("parser", PARSERS)
def test_reasons(parser: BillPdfParser) -> None:
    assert reason(parser, make_pdf(creation_date="D:2025", truncated=True)) == "truncated"
    assert reason(parser, make_pdf(creation_date="D:2025", encrypted=True)) == "encrypted"
    assert reason(parser, make_pdf(creation_date="D:2025", encrypted=True, info_in_objstm=True)) == "encrypted"
    assert reason(parser, make_pdf(creation_date=None)) == "no_creation_date"
    assert reason(parser, b"plain text\n%%EOF") == "not_pdf"


def test_truncated_is_checked_before_encrypted() -> None:
    assert reason(ELEC_BILL, make_pdf(creation_date=None, encrypted=True, truncated=True)) == "truncated"


def test_encrypt_metadata_alone_is_not_encryption() -> None:
    data = make_pdf(creation_date="D:2025").replace(b"/Producer", b"/EncryptMetadata false /Producer", 1)
    assert ELEC_BILL.inspect(NAME, data).source_ts == datetime(2025, 1, 1)
